import {readFile} from 'node:fs/promises';
import {createHash,webcrypto} from 'node:crypto';
import {loadSnapshot} from '/workspace/nml-pros004-readiness/web/snapshot.mjs';
const required=['PTS','PRA','REB','3PM','AST','RA','PR','TOV','TD','DD','BLK','STL','BLK+STL','PA'];
const files=[];
const snapshot=await loadSnapshot(async path=>{
 if(!path.startsWith('./data/')||path.includes('..'))throw new Error('Unsafe local artifact path');
 const raw=await readFile(new URL(path.slice(2),new URL('file:///workspace/nml-pros004-readiness/output/')));
 files.push({path,encoded_bytes:raw.byteLength,sha256:createHash('sha256').update(raw).digest('hex')});
 return new Response(raw);
},webcrypto);
if(snapshot.errors.length||snapshot.manifest.schema_version!==3)throw new Error('Invalid current public artifact');
const nba=snapshot.sports.find(s=>s.league==='NBA');
if(!nba||nba.forecasts.length!==6||nba.performance.length!==6)throw new Error('Lost original six historical bundles/grades');
for(const f of nba.forecasts){
 if(f.evidence_lane!=='RECONSTRUCTED_RESEARCH'||f.categories.length!==14||required.some(c=>!f.categories.some(x=>x.code===c)))throw new Error('Historical lane/category changed');
}
if(nba.offers.length||nba.candidates.length||nba.tickets.length||nba.future_availability.status!=='UNAVAILABLE')throw new Error('Unexpected qualified/future records');
if(!snapshot.pros004||snapshot.pros004.forecasts.length||snapshot.pros004.grades.length)throw new Error('Diagnostic records entered actual publication');
console.log(JSON.stringify({mode:'LOCAL_BUILT_ARTIFACT_ONLY',verified_at:new Date().toISOString(),build_commit:snapshot.manifest.build_commit,
manifest_schema:3,loaded_assets:files,legacy_forecast_bundles:6,legacy_statistical_grades:6,categories:required,
pros004_forecasts:0,pros004_grades:0,future_availability:nba.future_availability,coverage:nba.coverage,
public_deployment:false,genuine_issuance:0}));
